DO $branchit_reset$
DECLARE uid integer; pid integer; graduates_before jsonb; graduates_after jsonb;
BEGIN
LOCK TABLE usuarios, perfiles_egresado, perfiles_empresa, ofertas_empleo, postulaciones, archivos_portfolio IN SHARE ROW EXCLUSIVE MODE;
IF (SELECT version_num FROM alembic_version) IS DISTINCT FROM '0006_cierre_convocatorias' THEN RAISE EXCEPTION 'Esquema inesperado: ejecuta alembic upgrade head'; END IF;
IF (SELECT count(*) FROM usuarios WHERE tipo='empresa') <> 13 THEN RAISE EXCEPTION 'Cambió la cantidad de empresas; revisar antes de reiniciar'; END IF;
IF (SELECT count(*) FROM usuarios WHERE tipo='egresado') <> 2 THEN RAISE EXCEPTION 'Cambió la cantidad de egresados; revisar antes de reiniciar'; END IF;
IF (SELECT count(*) FROM ofertas_empleo) <> 101 THEN RAISE EXCEPTION 'Cambió la cantidad de ofertas; revisar antes de reiniciar'; END IF;
IF (SELECT count(*) FROM postulaciones) <> 3 THEN RAISE EXCEPTION 'Cambió la cantidad de postulaciones; revisar antes de reiniciar'; END IF;
IF (SELECT count(*) FROM archivos_portfolio a JOIN usuarios u ON u.id=a.usuario_id WHERE u.tipo='empresa') <> 2 THEN RAISE EXCEPTION 'Cambió la cantidad de archivos_empresa; revisar antes de reiniciar'; END IF;
SELECT jsonb_build_object(
        'usuarios',(SELECT jsonb_agg(to_jsonb(u) ORDER BY id) FROM usuarios u WHERE tipo='egresado'),
        'perfiles',(SELECT jsonb_agg(to_jsonb(p) ORDER BY id) FROM perfiles_egresado p),
        'archivos',(SELECT jsonb_agg(to_jsonb(a) ORDER BY a.id) FROM archivos_portfolio a JOIN usuarios u ON a.usuario_id=u.id WHERE u.tipo='egresado')) INTO graduates_before;
CREATE SCHEMA branchit_backup_20261018_reset_v2;
CREATE TABLE branchit_backup_20261018_reset_v2.usuarios AS SELECT * FROM usuarios WHERE tipo='empresa';
CREATE TABLE branchit_backup_20261018_reset_v2.perfiles_empresa AS TABLE perfiles_empresa;
CREATE TABLE branchit_backup_20261018_reset_v2.ofertas_empleo AS TABLE ofertas_empleo;
CREATE TABLE branchit_backup_20261018_reset_v2.postulaciones AS TABLE postulaciones;
CREATE TABLE branchit_backup_20261018_reset_v2.archivos_portfolio AS SELECT a.* FROM archivos_portfolio a JOIN usuarios u ON u.id=a.usuario_id WHERE u.tipo='empresa';
DELETE FROM postulaciones;
DELETE FROM ofertas_empleo;
DELETE FROM perfiles_empresa;
DELETE FROM archivos_portfolio WHERE usuario_id IN (SELECT id FROM usuarios WHERE tipo='empresa');
DELETE FROM usuarios WHERE tipo='empresa';
SELECT jsonb_build_object(
        'usuarios',(SELECT jsonb_agg(to_jsonb(u) ORDER BY id) FROM usuarios u WHERE tipo='egresado'),
        'perfiles',(SELECT jsonb_agg(to_jsonb(p) ORDER BY id) FROM perfiles_egresado p),
        'archivos',(SELECT jsonb_agg(to_jsonb(a) ORDER BY a.id) FROM archivos_portfolio a JOIN usuarios u ON a.usuario_id=u.id WHERE u.tipo='egresado')) INTO graduates_after;
IF graduates_before IS DISTINCT FROM graduates_after THEN RAISE EXCEPTION 'Se alteraron datos de egresados: se revierte todo'; END IF;
IF (SELECT count(*) FROM usuarios WHERE tipo='empresa') <> 10 OR (SELECT count(*) FROM perfiles_empresa) <> 10 OR (SELECT count(*) FROM ofertas_empleo) <> 100 OR (SELECT count(*) FROM postulaciones) <> 0 THEN RAISE EXCEPTION 'Cantidades inesperadas: se revierte todo'; END IF;
IF EXISTS (SELECT 1 FROM ofertas_empleo WHERE sueldo IS NULL OR sueldo <= 0 OR funciones IS NULL OR perfiles_deseados IS NULL OR condiciones_laborales IS NULL OR adaptada_discapacidad IS NULL OR NOT activa) THEN RAISE EXCEPTION 'Ofertas incompletas: se revierte todo'; END IF;
END $branchit_reset$;
